questionvariables.text:
colour1: rand([red, green, yellow, orange]);
colour2: rand([blue, white, black, purple]);

n1: rand(4)+3;
n2: rand(3)+2;

total: n1+n2;

pn1: n1/total;
pn2: n2/total;

p1n1: (n1-1)/(total-1);
p1n2: (n2-1)/(total-1);

p2n1: (n1-2)/(total-2);
p2n2: (n2-2)/(total-2);

p: n2/(total-2);
p1: n2/(total-1);
p2: (n1-1)/(total-2);
p3: n1/(total-1);
p4: (n1-1)/(total-2);

pro: pn1 * p1n1 * p;
pro1: pn1 * p1 * p4;
pro2: pn2 * p3 * p4;
ta1:pro + pro1 + pro2;
